#include <stdio.h>

int add(int a, int b) {
    return a + b;
}

int sub(int a, int b) {
    return a - b;
}

int main(void) {
    int (*op)(int, int) = add;
    printf("%d\n", op(7, 2));
    op = sub;
    printf("%d\n", op(7, 2));
    return 0;
}

#include <stdio.h>

void show(int x) {
    printf("碗里是 %d\n", x);
}

void show_double(int x) {
    printf("翻倍是 %d\n", x * 2);
}

void each(int a[], int n, void (*visit)(int)) {
    for (int i = 0; i < n; i++) {
        visit(a[i]);
    }
}

int main(void) {
    int bowl[3] = {3, 5, 7};
    each(bowl, 3, show);
    each(bowl, 3, show_double);
    return 0;
}
